/**
 * Public environment values (#1650).
 *
 * Next.js inlines `process.env.NEXT_PUBLIC_X` only where it appears literally,
 * so every client variable is spelled out here once. The `satisfies` clause
 * makes a variable declared in spec.ts but missing here a type error.
 */
import { CLIENT_ENV_VARS, checkEnv, type ClientEnvKey, type EnvIssue } from "./spec";

export const clientEnv = {
  NEXT_PUBLIC_STELLAR_NETWORK: process.env.NEXT_PUBLIC_STELLAR_NETWORK,
  NEXT_PUBLIC_STELLAR_NETWORK_PASSPHRASE: process.env.NEXT_PUBLIC_STELLAR_NETWORK_PASSPHRASE,
  NEXT_PUBLIC_SOROBAN_RPC_URL: process.env.NEXT_PUBLIC_SOROBAN_RPC_URL,
  NEXT_PUBLIC_HORIZON_URL: process.env.NEXT_PUBLIC_HORIZON_URL,
  NEXT_PUBLIC_FACTORY_CONTRACT_ID: process.env.NEXT_PUBLIC_FACTORY_CONTRACT_ID,
  NEXT_PUBLIC_USDC_CONTRACT_ID: process.env.NEXT_PUBLIC_USDC_CONTRACT_ID,
  NEXT_PUBLIC_XLM_CONTRACT_ID: process.env.NEXT_PUBLIC_XLM_CONTRACT_ID,
  NEXT_PUBLIC_STAKING_CONTRACT_ID: process.env.NEXT_PUBLIC_STAKING_CONTRACT_ID,
  NEXT_PUBLIC_RWA_VAULT_CONTRACT_ID: process.env.NEXT_PUBLIC_RWA_VAULT_CONTRACT_ID,
  NEXT_PUBLIC_ORACLE_CONTRACT_ID: process.env.NEXT_PUBLIC_ORACLE_CONTRACT_ID,
  NEXT_PUBLIC_USDC_ISSUER: process.env.NEXT_PUBLIC_USDC_ISSUER,
  NEXT_PUBLIC_EURC_ISSUER: process.env.NEXT_PUBLIC_EURC_ISSUER,
  NEXT_PUBLIC_API_BASE_URL: process.env.NEXT_PUBLIC_API_BASE_URL,
  NEXT_PUBLIC_APP_ORIGIN: process.env.NEXT_PUBLIC_APP_ORIGIN,
  NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL,
  NEXT_PUBLIC_DEMO_ARENA_ID: process.env.NEXT_PUBLIC_DEMO_ARENA_ID,
  NEXT_PUBLIC_TELEMETRY_POLL_INTERVAL_MS: process.env.NEXT_PUBLIC_TELEMETRY_POLL_INTERVAL_MS,
  NEXT_PUBLIC_COINGECKO_SIMPLE_PRICE_URL: process.env.NEXT_PUBLIC_COINGECKO_SIMPLE_PRICE_URL,
  NEXT_PUBLIC_VAPID_PUBLIC_KEY: process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,
  NEXT_PUBLIC_PASSKEY_DEMO_MODE: process.env.NEXT_PUBLIC_PASSKEY_DEMO_MODE,
  NEXT_PUBLIC_USE_MOCK_PROFILE: process.env.NEXT_PUBLIC_USE_MOCK_PROFILE,
  NEXT_PUBLIC_SENTRY_DSN: process.env.NEXT_PUBLIC_SENTRY_DSN,
  NEXT_PUBLIC_SENTRY_ENVIRONMENT: process.env.NEXT_PUBLIC_SENTRY_ENVIRONMENT,
  NEXT_PUBLIC_SENTRY_RELEASE: process.env.NEXT_PUBLIC_SENTRY_RELEASE,
} satisfies Record<ClientEnvKey, string | undefined>;

/** Problems with the public environment, without throwing. */
export function checkClientEnv(): EnvIssue[] {
  return checkEnv(CLIENT_ENV_VARS, clientEnv);
}
